#include <iostream>
#include <vector>
#include <algorithm>
#include <cassert>
#include <chrono>
#include <ext/pb_ds/assoc_container.hpp>
using namespace std;
using namespace __gnu_pbds;

auto get_random_ptr = [] { char *p = new char; delete p; return (uint64_t) p; };

struct hash_func {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }

    uint64_t operator()(uint64_t x) const {
        static const uint64_t seed = splitmix64(chrono::steady_clock::now().time_since_epoch().count() * (get_random_ptr() | 1));
        return splitmix64(x ^ seed);
    }
};

const int MODULUS_CONST = 1e9 + 7;

struct modNumberType {
    int val;

    modNumberType(long long v = 0) {
        if (v < 0) v %= MODULUS_CONST, v += MODULUS_CONST;
        if (v >= MODULUS_CONST) v %= MODULUS_CONST;
        val = v;
    }

    static int extended_gcd(int a, int m, int &x, int &y) {
        if (m == 0) {
            x = 1; y = 0;
            return a;
        }
        int g = extended_gcd(m, a % m, y, x);
        y -= (a / m) * x;
        return g;
    }

    static int mod_inverse(int a, int m = MODULUS_CONST) {
        int x, y;
        extended_gcd(a, m, x, y);
        return (x % m + m) % m;
    }

    explicit operator int() const { return val; }

    modNumberType& operator+=(const modNumberType &other) {
        val += other.val;
        if (val >= MODULUS_CONST) val -= MODULUS_CONST;
        return *this;
    }

    modNumberType& operator-=(const modNumberType &other) {
        val -= other.val;
        if (val < 0) val += MODULUS_CONST;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MODULUS_CONST) {
#if !defined(_WIN32) || defined(_WIN64)
        return x % m;
#endif
        unsigned high = x >> 32, low = (unsigned) x;
        unsigned q, r;
        asm("divl %4\n"
            : "=a" (q), "=d" (r)
            : "d" (high), "a" (low), "r" (m));
        return r;
    }

    modNumberType& operator*=(const modNumberType &other) {
        val = fast_mod((uint64_t) val * other.val);
        return *this;
    }

    modNumberType& operator/=(const modNumberType &other) {
        return *this *= modNumberType::inverse(other.val);
    }

    friend modNumberType operator+(const modNumberType &a, const modNumberType &b) { return modNumberType(a) += b; }
    friend modNumberType operator-(const modNumberType &a, const modNumberType &b) { return modNumberType(a) -= b; }
    friend modNumberType operator*(const modNumberType &a, const modNumberType &b) { return modNumberType(a) *= b; }
    friend modNumberType operator/(const modNumberType &a, const modNumberType &b) { return modNumberType(a) /= b; }

    modNumberType& operator++() {
        val = (val == MODULUS_CONST - 1) ? 0 : val + 1;
        return *this;
    }

    modNumberType& operator--() {
        val = (val == 0) ? MODULUS_CONST - 1 : val - 1;
        return *this;
    }

    modNumberType operator++(int) { modNumberType tmp = *this; ++(*this); return tmp; }
    modNumberType operator--(int) { modNumberType tmp = *this; --(*this); return tmp; }

    modNumberType operator-() const {
        return val == 0 ? 0 : MODULUS_CONST - val;
    }

    bool operator==(const modNumberType &other) const { return val == other.val; }
    bool operator!=(const modNumberType &other) const { return val != other.val; }

    static modNumberType inverse(int a) {
        return modNumberType(modNumberType::mod_inv(a));
    }

    modNumberType pow(long long p) const {
        assert(p >= 0);
        modNumberType base = *this, result = 1;
        while (p > 0) {
            if (p & 1) result *= base;
            base *= base;
            p >>= 1;
        }
        return result;
    }
};

const int MAX_NODES_COUNT = 10;
int total_N_value;
modular prob_matrix[MAX_NODES_COUNT][MAX_NODES_COUNT];

int main() {
    cin >> total_N_value;
    for (int i = 0; i < total_N_value; ++i)
        for (int j = 0; j < total_N_value; ++j) {
            int p;
            cin >> p;
            prob_matrix[i][j] = modular(p) / modular(100);
        }

    vector<vector<int>> masks_by_popcount(total_N_value + 1);
    vector<int> lookup_idx(1 << total_N_value, -1);
    for (int m = 0; m < (1 << total_N_value); ++m) {
        int c = __builtin_popcount(m);
        lookup_idx[m] = masks_by_popcount[c].size();
        masks_by_popcount[c].push_back(m);
    }

    gp_hash_table<long long, modular, hash_func> possible_states_map;
    possible_states_map[1LL << lookup_idx[0]] = 1;

    for (int left_part = 0; left_part < total_N_value; ++left_part) {
        gp_hash_table<long long, modular, hash_func> new_states_map;
        vector<modular> product_mask_vec(1 << total_N_value, 1);
        for (int current_mask = 0; current_mask < (1 << total_N_value); ++current_mask) {
            for (int r = 0; r < total_N_value; ++r) {
                product_mask_vec[current_mask] *= (current_mask >> r & 1) ? prob_matrix[left_part][r] : modular(1) - prob_matrix[left_part][r];
            }
        }
        vector<long long> new_bits_vec(total_N_value, 0);
        vector<modular> new_possible_mask_vec(1 << total_N_value, 0);
        for (auto &state : possible_states_map) {
            long long current_mask_state = state.first;
            modular prob_value = state.second;
            fill(new_bits_vec.begin(), new_bits_vec.end(), 0);
            for (int m : masks_by_popcount[left_part]) {
                if (current_mask_state >> lookup_idx[m] & 1) {
                    for (int i = 0; i < total_N_value; ++i) {
                        if ((m >> i & 1) == 0) {
                            new_bits_vec[i] |= 1LL << lookup_idx[m | 1 << i];
                        }
                    }
                }
            }
            fill(new_possible_mask_vec.begin(), new_possible_mask_vec.end(), 0);
            for (int curr_mask = 1; curr_mask < (1 << total_N_value); ++curr_mask) {
                new_possible_mask_vec[curr_mask] = new_possible_mask_vec[curr_mask & (curr_mask - 1)] | new_bits_vec[__builtin_ctz(curr_mask)];
                new_states_map[new_possible_mask_vec[curr_mask]] += prob_value * product_mask_vec[curr_mask];
            }
        }
        possible_states_map = move(new_states_map);
    }

    modular total_res = 0;
    for (auto &state : possible_states_map) {
        if (state.first >> lookup_idx[(1 << total_N_value) - 1] & 1)
            total_res += state.second;
    }
    cout << (int)total_res << '\n';
}
